const planningBridge="// Storage adapter for the integrated copy. The uploaded original is kept unchanged.\n(()=>{const seed=window.__PLANNING_BOOT__;let current=seed.state?JSON.stringify(seed.state):null,version=seed.version,pending=null,busy=false,blocked=false;\nconst notify=(state,message)=>parent.postMessage({type:'planning-status',state,message},location.origin);\nasync function flush(){if(busy||blocked||pending===null)return;busy=true;const snapshot=pending;pending=null;notify('saving','Guardando planificación…');try{const r=await fetch('/api/planning',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:JSON.parse(snapshot),expectedVersion:version})});if(!r.ok){const error=new Error(await r.text());error.status=r.status;throw error}const result=await r.json();version=result.version;notify('saved','Planificación guardada y compartida entre administradores.')}catch(e){pending=pending||snapshot;blocked=true;notify('error',e.message||'Cambios sin sincronizar. Descarga un respaldo antes de salir.')}finally{busy=false;if(!blocked&&pending!==null)flush()}}\nwindow.planningStorage={getItem:()=>current,setItem:(key,value)=>{current=value;pending=value;queueMicrotask(flush)}};\nwindow.addEventListener('beforeunload',e=>{if(busy||pending!==null){e.preventDefault();e.returnValue=''}});\nwindow.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;if(e.data?.type==='planning-backup'&&typeof backup==='function')backup();});\nwindow.addEventListener('DOMContentLoaded',()=>notify('ready','Planificación integrada. Los cambios se guardan en el mural.'));\n})();\n\n// Native-feeling navigation: the mural owns the only visible menu.\nif(window.self!==window.top){\n document.documentElement.classList.add('mural-integrated');\n const planningPages=['Resumen','Comisiones','Tareas','Cotizaciones','Presupuesto','Participantes y abonos'];\n let sizeQueued=false;\n function reportSize(){if(sizeQueued)return;sizeQueued=true;requestAnimationFrame(()=>{sizeQueued=false;const main=document.querySelector('main');if(main)parent.postMessage({type:'planning-size',height:Math.ceil(main.getBoundingClientRect().height+32)},location.origin)})}\n window.addEventListener('DOMContentLoaded',()=>{const previousGo=go;go=function(target){previousGo(target);parent.postMessage({type:'planning-page',page:target},location.origin);reportSize()};new ResizeObserver(reportSize).observe(document.querySelector('main'));new MutationObserver(reportSize).observe(document.querySelector('main'),{subtree:true,childList:true,characterData:true});reportSize()});\n window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.type!=='planning-navigate'||!planningPages.includes(e.data.page))return;go(e.data.page)});\n}\nif(window.self!==window.top)window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.type!=='planning-viewport')return;const top=Number(e.data.top),height=Number(e.data.height);if(Number.isFinite(top)&&Number.isFinite(height)){document.documentElement.style.setProperty('--planning-dialog-top',Math.max(16,top)+'px');document.documentElement.style.setProperty('--planning-dialog-height',Math.max(200,height)+'px')}});\n\n// Keep the original report actions and filters on one compact row.\nif(window.self!==window.top)window.addEventListener('DOMContentLoaded',()=>{\n function compactReportControls(){const content=document.getElementById('content'),exportBar=document.getElementById('reportToolbar'),exportMenu=exportBar?.querySelector('.export-menu');if(!content)return;const row=page==='Resumen'?content.querySelector('.summary-shortcuts'):content.querySelector('.tools');if(!row)return;row.classList.add('compact-report-controls');if(exportMenu){row.appendChild(exportMenu);exportBar.remove()}const add=row.querySelector('button.primary');if(add)add.textContent=page==='Comisiones'?'+ Agregar comisión':'+ Agregar';const search=row.querySelector('input[aria-label=\"Buscar\"]');if(search){search.placeholder='Buscar…';search.style.maxWidth='170px'}const commissions=row.querySelector('select[aria-label=\"Filtrar comisión\"]');if(commissions){commissions.options[0].textContent='Comisiones';commissions.style.maxWidth='190px'}const state=row.querySelector('#stateFilter');if(state){state.options[0].textContent='Estado';state.style.maxWidth='170px'}if(page==='Tareas')row.querySelector('#responsibleFilter')?.remove();if(page==='Presupuesto')row.querySelector('#paymentStateFilter')?.remove();}\n const previousRender=render;render=function(){if(page==='Tareas')ownerFilter='';if(page==='Presupuesto')paymentFilter='';previousRender();compactReportControls()};compactReportControls();\n});\n";
