const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
const fail=(message,status=400)=>new Response(message,{status,headers:{'Content-Type':'text/plain;charset=utf-8','Cache-Control':'no-store'}});
const validId=x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(x);
async function getState(env){
 await env.DB.prepare("INSERT OR IGNORE INTO mural_state (id,payload,version) VALUES ('shared',?,1)").bind(JSON.stringify({albums:[],photos:[],creations:[]})).run();
 const row=await env.DB.prepare("SELECT payload,version FROM mural_state WHERE id='shared'").first();
 return {...JSON.parse(row.payload),_version:row.version};
}
async function setState(env,data,expected){const payload=JSON.stringify({albums:data.albums,photos:data.photos,creations:data.creations});if(new TextEncoder().encode(payload).length>1500000)throw Error('Metadatos demasiado grandes');const result=await env.DB.prepare('UPDATE mural_state SET payload=?,version=version+1 WHERE id=? AND version=?').bind(payload,'shared',expected).run();return result.meta.changes===1}
async function changeState(env,fn){for(let i=0;i<3;i++){const d=await getState(env),out=fn(d);if(await setState(env,d,d._version))return out}throw Error('Otra sesión actualizó la biblioteca. Actualiza y vuelve a guardar.')}
function activeState(d){const albums=d.albums.filter(x=>!x.deletedAt),ids=new Set(albums.map(x=>x.id));return {albums,photos:d.photos.filter(p=>!p.deletedAt&&ids.has(p.album)),creations:d.creations.filter(x=>!x.deletedAt&&(!x.album||ids.has(x.album))&&(x.kind!=='video'||!!x.asset)),_version:d._version}}
function localMediaUrl(x){return typeof x==='string'&&/^\/api\/(files|photo)\/[a-zA-Z0-9_-]{1,100}$/.test(x)}
function validateState(s){return s&&Array.isArray(s.albums)&&Array.isArray(s.photos)&&Array.isArray(s.creations)&&s.albums.length<=3000&&s.photos.length<=15000&&s.creations.length<=3000&&s.albums.every(x=>validId(x.id)&&typeof x.title==='string'&&x.title.length<=100&&/^\d{4}-\d{2}-\d{2}$/.test(x.date))&&s.photos.every(x=>validId(x.id)&&validId(x.album)&&localMediaUrl(x.src))&&s.creations.every(x=>validId(x.id)&&typeof x.title==='string'&&x.title.length<=100&&['video','collage'].includes(x.kind)&&Array.isArray(x.photoIds)&&(!x.album||validId(x.album)&&s.albums.some(a=>a.id===x.album))&&(!x.thumbnail||localMediaUrl(x.thumbnail))&&(!x.asset||x.asset.remote===true&&localMediaUrl(x.asset.url))&&(!x.audio||x.audio.remote===true&&localMediaUrl(x.audio.url))&&(x.demoPhotos||[]).every(p=>/^data:image\/svg\+xml(?:;[^,]*)?,/.test(p.src)))}
async function mediaResponse(request,bucket,key){const head=await bucket.head(key);if(!head)return fail('Archivo no encontrado',404);const headers=new Headers({'Content-Type':head.httpMetadata?.contentType||'application/octet-stream','Accept-Ranges':'bytes','X-Content-Type-Options':'nosniff','Cache-Control':'private,max-age=60'});if(new URL(request.url).searchParams.has('download'))headers.set('Content-Disposition',"attachment; filename*=UTF-8''"+encodeURIComponent(head.customMetadata?.name||'recuerdo'));let range,status=200;const raw=request.headers.get('Range');if(raw){const m=/^bytes=(\d*)-(\d*)$/.exec(raw);if(!m||!m[1]&&!m[2])return fail('Rango no válido',416);const start=m[1]?Number(m[1]):Math.max(0,head.size-Number(m[2])),end=m[1]?(m[2]?Math.min(head.size-1,Number(m[2])):head.size-1):head.size-1;if(start>end||start>=head.size)return fail('Rango no disponible',416);range={offset:start,length:end-start+1};headers.set('Content-Range',`bytes ${start}-${end}/${head.size}`);headers.set('Content-Length',String(range.length));status=206}else headers.set('Content-Length',String(head.size));if(request.method==='HEAD')return new Response(null,{status,headers});const obj=await bucket.get(key,range?{range}:undefined);return new Response(obj.body,{status,headers})}
const SESSION_COOKIE='__Host-mural-session';
async function digest(value){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function sessionCookie(request){return (request.headers.get('Cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith(SESSION_COOKIE+'='))?.slice(SESSION_COOKIE.length+1)||''}
async function authenticatedAdmin(request,env){const token=sessionCookie(request);if(!/^[a-f0-9-]{72}$/.test(token))return false;const row=await env.DB.prepare('SELECT payload,version FROM mural_state WHERE id=?').bind('session_'+await digest(token)).first();return !!row&&JSON.parse(row.payload).expires>Date.now()}
async function adminAuth(request,env,path){if(request.headers.get('Origin')!==new URL(request.url).origin)return fail('Origen no autorizado',403);if(path==='/api/logout'){const token=sessionCookie(request);if(token)await env.DB.prepare('DELETE FROM mural_state WHERE id=?').bind('session_'+await digest(token)).run();return new Response(JSON.stringify({ok:true}),{headers:{'Content-Type':'application/json','Cache-Control':'no-store','Set-Cookie':SESSION_COOKIE+'=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0'}})}
 if(!env.MURAL_ADMIN_PASSWORD)return fail('La clave de administración no está configurada.',503);
 const window=Math.floor(Date.now()/900000),ip=request.headers.get('CF-Connecting-IP')||'unknown',key='login_'+window+'_'+await digest(ip);
 const attempt=await env.DB.prepare('SELECT payload,version FROM mural_state WHERE id=?').bind(key).first();if(attempt?.version>=5)return fail('Demasiados intentos. Intenta nuevamente en 15 minutos.',429);
 if(Number(request.headers.get('Content-Length'))>1024)return fail('Solicitud demasiado grande',413);let password;try{password=(await request.json()).password}catch{return fail('Solicitud no válida')}
 if(typeof password!=='string'||password.length>200)return fail('Clave incorrecta',401);
 const a=await digest(password),b=await digest(env.MURAL_ADMIN_PASSWORD);let different=0;for(let i=0;i<a.length;i++)different|=a.charCodeAt(i)^b.charCodeAt(i);
 if(different){await env.DB.prepare('INSERT INTO mural_state (id,payload,version) VALUES (?,?,1) ON CONFLICT(id) DO UPDATE SET version=version+1').bind(key,'{}').run();return fail('Clave incorrecta',401)}
 await env.DB.prepare('DELETE FROM mural_state WHERE id=?').bind(key).run();const token=crypto.randomUUID()+crypto.randomUUID();await env.DB.prepare('INSERT INTO mural_state (id,payload,version) VALUES (?,?,1)').bind('session_'+await digest(token),JSON.stringify({expires:Date.now()+28800000})).run();return new Response(JSON.stringify({ok:true}),{headers:{'Content-Type':'application/json','Cache-Control':'no-store','Set-Cookie':SESSION_COOKIE+'='+token+'; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=28800'}});
}

function validPlanning(data){const keys=['commissions','tasks','budget','people','payments','agenda'];return data&&typeof data==='object'&&!Array.isArray(data)&&data.settings&&typeof data.settings.name==='string'&&keys.every(k=>Array.isArray(data[k])&&data[k].length<=15000)&&new TextEncoder().encode(JSON.stringify(data)).length<=1500000}
async function planningRecord(env){const row=await env.DB.prepare('SELECT payload,version FROM mural_state WHERE id=?').bind('planning-main').first();return row?{state:JSON.parse(row.payload),version:row.version}:{state:null,version:0}}
async function planningRoute(request,env,path){if(!await authenticatedAdmin(request,env))return fail('Ingresa la clave en Administrar para abrir la planificación.',403);if(request.method==='GET'){const record=await planningRecord(env);if(path==='/api/planning')return json(record);const safe=JSON.stringify(record).replace(/</g,'\\u003c');const boot='<script>window.__PLANNING_BOOT__='+safe+';'+planningBridge+'</script>';return new Response(planningOriginal.replace('<html lang="es">',new URL(request.url).searchParams.get('integrated')==='1'?'<html lang="es" class="mural-integrated">':'<html lang="es">').replace('</style>','\n'+planningIntegratedCss+'</style>').replace('<script>',boot+'<script>').replaceAll('localStorage','planningStorage'),{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store','X-Frame-Options':'SAMEORIGIN','Content-Security-Policy':"frame-ancestors 'self'"}})}
if(path==='/api/planning'&&request.method==='POST'){if(request.headers.get('Origin')!==new URL(request.url).origin)return fail('Origen no autorizado',403);if(Number(request.headers.get('Content-Length'))>1600000)return fail('Planificación demasiado grande',413);const {state,expectedVersion}=await request.json();if(!validPlanning(state)||!Number.isInteger(expectedVersion))return fail('La planificación no es válida.');const payload=JSON.stringify(state);let result;if(expectedVersion===0)result=await env.DB.prepare('INSERT OR IGNORE INTO mural_state (id,payload,version) VALUES (?,?,1)').bind('planning-main',payload).run();else result=await env.DB.prepare('UPDATE mural_state SET payload=?,version=version+1 WHERE id=? AND version=?').bind(payload,'planning-main',expectedVersion).run();if(result.meta.changes!==1)return fail('Otra sesión modificó la planificación. Descarga un respaldo de tus cambios antes de recargar.',409);return json({version:expectedVersion+1})}return fail('No encontrado',404)}

export default {async fetch(request,env){try{const u=new URL(request.url),path=u.pathname;if(path==='/'||path==='/index.html')return new Response(page,{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});if(path==='/planning'||path==='/api/planning')return planningRoute(request,env,path);if(!path.startsWith('/api/'))return fail('No encontrado',404);if(path==='/api/health')return json({storage:!!env.BUCKET,database:!!env.DB});if(!env.DB||!env.BUCKET)return fail('El almacenamiento compartido aún no está listo.',503);const email='';if(['/api/login','/api/logout'].includes(path)&&request.method==='POST')return adminAuth(request,env,path);const admin=await authenticatedAdmin(request,env),write=!['GET','HEAD'].includes(request.method);if(write&&request.headers.get('Origin')!==u.origin)return fail('Origen no autorizado',403);if(write&&!admin)return fail('Solo el administrador puede modificar la biblioteca.',403);
if(path==='/api/data'&&request.method==='GET'){const d=await getState(env);return json({...admin?d:activeState(d),role:admin?'admin':'viewer',user:{email}})}
if(path==='/api/state'&&request.method==='POST'){if(Number(request.headers.get('content-length'))>1800000)return fail('La información es demasiado grande.',413);const {state,expectedVersion}=await request.json();if(!validateState(state)||!Number.isInteger(expectedVersion))return fail('La biblioteca contiene información o archivos no válidos.');if(!await setState(env,state,expectedVersion))return fail('La biblioteca cambió en otra sesión. Actualiza y vuelve a guardar.',409);return json({version:expectedVersion+1})}
if(path==='/api/album'&&request.method==='POST'){const d=await request.json();if(!d.title?.trim()||d.title.length>100||!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!['Integración','Celebración','Salida','Reunión','Otros'].includes(d.type)||d.id&&!validId(d.id))return fail('Revisa el nombre y la fecha del álbum.');const a={id:d.id||crypto.randomUUID(),title:d.title.trim(),date:d.date,type:d.type,description:String(d.description||'').slice(0,500)};await changeState(env,s=>{const existing=s.albums.find(x=>x.id===a.id);if(existing)Object.assign(a,{...existing,...a});s.albums=s.albums.filter(x=>x.id!==a.id);s.albums.unshift(a)});return json(a)}
if(path==='/api/upload'&&request.method==='POST'){const mime=(request.headers.get('content-type')||'').split(';')[0],size=Number(request.headers.get('content-length'));if(!Number.isFinite(size)||size<=0)return fail('No se pudo determinar el tamaño del archivo.',411);if(!/^(image\/(jpeg|png|webp)|video\/(mp4|webm|quicktime)|audio\/[a-zA-Z0-9.+-]+)$/.test(mime))return fail('Formato de archivo no compatible.');if(size>80*1024*1024)return fail('Máximo 80 MB por archivo.',413);const id=crypto.randomUUID();await env.BUCKET.put('files/'+id,request.body,{httpMetadata:{contentType:mime},customMetadata:{name:(u.searchParams.get('name')||'recuerdo').slice(0,180)}});return json({remote:true,id,url:'/api/files/'+id,mime,size})}
if(path==='/api/photo'&&request.method==='POST'){if(Number(request.headers.get('content-length'))>16*1024*1024)return fail('Máximo 15 MB por foto.',413);const form=await request.formData(),f=form.get('file'),album=form.get('album');if(!f||typeof f==='string'||!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>15*1024*1024)return fail('Usa JPG, PNG o WebP de hasta 15 MB.');const d=await getState(env);if(!d.albums.some(x=>x.id===album&&!x.deletedAt))return fail('El álbum no existe.');const id=crypto.randomUUID(),p={id,album,name:f.name.slice(0,180),favorite:false,created:new Date().toISOString(),src:'/api/files/'+id};await env.BUCKET.put('files/'+id,f.stream(),{httpMetadata:{contentType:f.type},customMetadata:{name:p.name}});await changeState(env,s=>s.photos.push(p));return json(p)}
if(path==='/api/favorite'&&request.method==='POST'){const d=await request.json();let p;await changeState(env,s=>{p=s.photos.find(x=>x.id===d.id);if(p)p.favorite=!!d.favorite});return p?json(p):fail('Foto no encontrada',404)}
const photo=/^\/api\/photo\/([a-zA-Z0-9_-]{1,100})$/.exec(path);if(photo&&request.method==='DELETE'){await changeState(env,s=>{const p=s.photos.find(x=>x.id===photo[1]);if(p)p.deletedAt=new Date().toISOString()});return json({ok:true})}
const file=/^\/api\/(files|photo)\/([a-zA-Z0-9_-]{1,100})$/.exec(path);if(file&&['GET','HEAD'].includes(request.method)){if(!admin){const d=activeState(await getState(env)),ref=path;if(!d.photos.some(p=>p.src===ref)&&!d.creations.some(p=>p.thumbnail===ref||p.asset?.url===ref||p.audio?.url===ref))return fail('Archivo no disponible',404)}return mediaResponse(request,env.BUCKET,(file[1]==='photo'?'photos/':'files/')+file[2])}return fail('No encontrado',404);
}catch(e){console.error('Mural request failed',e.message);return fail('No se pudo completar la operación. '+(e.message?.includes('Otra sesión')?e.message:'Actualiza la página e intenta nuevamente.'),500)}}};
